class MinHeap {
  constructor() { this.heap = []; }
  parent(i) { return Math.floor((i-1)/2); }
  left(i)   { return 2*i+1; }
  right(i)  { return 2*i+2; }
  peek()    { return this.heap[0]; }
  size()    { return this.heap.length; }

  push(val) { this.heap.push(val); this._up(this.heap.length-1); }

  pop() {
    if (this.size()===1) return this.heap.pop();
    const min=this.heap[0];
    this.heap[0]=this.heap.pop();
    this._down(0);
    return min;
  }

  _up(i) {
    while (i>0 && this.heap[this.parent(i)]>this.heap[i]) {
      [this.heap[this.parent(i)],this.heap[i]]=[this.heap[i],this.heap[this.parent(i)]];
      i=this.parent(i);
    }
  }

  _down(i) {
    const n=this.size();
    while (true) {
      let s=i,l=this.left(i),r=this.right(i);
      if (l<n && this.heap[l]<this.heap[s]) s=l;
      if (r<n && this.heap[r]<this.heap[s]) s=r;
      if (s===i) break;
      [this.heap[s],this.heap[i]]=[this.heap[i],this.heap[s]]; i=s;
    }
  }
}

// Top K largest via min-heap of size K
function topK(nums, k) {
  const h=new MinHeap();
  for (const n of nums) { h.push(n); if (h.size()>k) h.pop(); }
  return h.heap;
}
